<script setup>
import { ref } from 'vue';
import { apiFetch } from '../services/api';
const email = ref(''); const password = ref(''); const name = ref(''); const storeName = ref(''); const isVendor = ref(false); const register = ref(false); const error = ref('');
async function submit() { error.value = ''; try { const endpoint = register.value ? '/auth/register' : '/auth/login'; const body = register.value ? { name: name.value, email: email.value, password: password.value, is_vendor: isVendor.value, storeName: isVendor.value ? storeName.value : undefined } : { email: email.value, password: password.value }; const response = await apiFetch(endpoint, { method: 'POST', body: JSON.stringify(body) }); if (response.token) localStorage.setItem('token', response.token); if (response.user) localStorage.setItem('user', JSON.stringify(response.user)); window.location.href = 'index.html'; } catch (e) { error.value = e.message; } }
</script>
<template><section class="login-page"><form class="card" @submit.prevent="submit"><div class="logo-row"><div class="logo-icon">LC</div><div class="brand">LocalCart</div><p class="subtitle">{{ register ? 'Create your account' : 'Welcome back' }}</p></div><div class="tabs"><button class="tab-btn" :class="{ active: !register }" type="button" @click="register = false">Log in</button><button class="tab-btn" :class="{ active: register }" type="button" @click="register = true">Register</button></div><div v-if="register" class="form-group"><label class="field-label">Name</label><input v-model="name" required type="text" /></div><div v-if="register" class="form-group"><label><input v-model="isVendor" type="checkbox"> I’m registering as a vendor</label></div><div v-if="register && isVendor" class="form-group"><label class="field-label">Store name</label><input v-model="storeName" required type="text" /></div><div class="form-group"><label class="field-label">Email</label><input v-model="email" required type="email" /></div><div class="form-group"><label class="field-label">Password</label><input v-model="password" required type="password" /></div><p v-if="error" class="error-message">{{ error }}</p><button class="btn-primary" type="submit">{{ register ? 'Create account' : 'Log in' }}</button></form></section></template>
